{"text":"[Reading 27 lines from start (total: 27 lines, 0 remaining)]\n\n\n\"\"\"\nRisk Worker - VaR, Position Limit, Correlation Check via GNN\n\"\"\"\nclass RiskWorker:\n    def __init__(self, max_alloc_per_strategy=0.20, max_portfolio_var=0.02):\n        self.max_alloc = max_alloc_per_strategy\n        self.max_var = max_portfolio_var\n        \n    def check(self, portfolio, new_strategy, alloc_pct):\n        # 1. Position limit\n        if alloc_pct > self.max_alloc:\n            return {\"passed\": False, \"reason\": f\"เกิน {self.max_alloc*100}% ต่อกลยุทธ์ - Risk Worker Block\"}\n        # 2. Correlation via GNN - ถ้า correlation สูงกับพอร์ตเดิม\n        corr = 0.75 # mock from GNN\n        if corr > 0.85:\n            return {\"passed\": False, \"reason\": \"Correlation สูงเกิน 0.85 กับพอร์ตเดิม - เสี่ยง\"}\n        # 3. VaR\n        var = 0.015\n        if var > self.max_var:\n            return {\"passed\": False, \"reason\": f\"VaR {var} เกิน {self.max_var}\"}\n        \n        return {\"passed\": True, \"var\": var, \"corr\": corr, \"message\": \"Risk Check Passed\"}\n\nif __name__ == \"__main__\":\n    worker = RiskWorker()\n    print(worker.check({}, {}, 0.15))\n\n[executed on device: 10_3_6_9 (85294689-03d5-431e-abd5-9e27d4c94814)]"}